import React, { useState } from 'react';

const Training = ({ onTrainingComplete }) => {
  const [ejSessions, setEjSessions] = useState([]);
  const [trainingStatus, setTrainingStatus] = useState('idle');
  const [trainingResults, setTrainingResults] = useState(null);
  const [loadingStatus, setLoadingStatus] = useState('');
  const [config, setConfig] = useState({
    textWeight: 0.6,
    statisticalWeight: 0.4,
    threshold: 0.5
  });

  const loadFromProcessedData = async () => {
    setLoadingStatus('Loading from processed EJ data (same source as DeepLog)...');
    try {
      // Load from processed data without sending file or text
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:8001'}/api/load_ej_sessions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          include_errors: false,  // Start with normal sessions only
          limit: 100  // Limit for testing
        })
      });

      const data = await response.json();
      if (data.success) {
        setEjSessions(data.sessions);
        setLoadingStatus(`✅ Loaded ${data.count} EJ sessions from ${data.data_source}`);
        alert(`Successfully loaded real EJ session data!

📊 Source: ${data.data_source}
📝 Sessions: ${data.count}
🎯 Same data source as DeepLog dashboard

Ready for ensemble training!`);
      } else {
        throw new Error(data.message || 'No processed data found');
      }
    } catch (error) {
      console.error('Loading from processed data failed:', error);
      setLoadingStatus(`Error: ${error.message}`);
      alert(`Could not load from processed data: ${error.message}

💡 Tip: This loads from the same processed EJ data that DeepLog uses. Ensure the EJ rule-based processor has been run to generate the data files.`);
    }
  };

  const handleFileUpload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    setLoadingStatus('Loading EJ sessions...');
    try {
      const formData = new FormData();
      formData.append('file', file);

      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:8001'}/api/load_ej_sessions`, {
        method: 'POST',
        body: formData,
      });

      const data = await response.json();
      if (data.success) {
        setEjSessions(data.sessions);
        setLoadingStatus(`Loaded ${data.count} EJ sessions from ${data.source}`);
      } else {
        throw new Error(data.error || 'Failed to load sessions');
      }
    } catch (error) {
      console.error('File upload failed:', error);
      setLoadingStatus(`Error: ${error.message}`);
    }
  };

  const handleTextInput = async (text) => {
    if (!text.trim()) return;

    setLoadingStatus('Sessionizing EJ log text...');
    try {
      const formData = new FormData();
      formData.append('text', text);

      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:8001'}/api/sessionize`, {
        method: 'POST',
        body: formData,
      });

      const data = await response.json();
      if (data.success) {
        setEjSessions(data.sessions);
        setLoadingStatus(`Sessionized into ${data.count} EJ sessions`);
      } else {
        throw new Error(data.error || 'Failed to sessionize');
      }
    } catch (error) {
      console.error('Sessionization failed:', error);
      setLoadingStatus(`Error: ${error.message}`);
    }
  };

  const trainModel = async () => {
    if (ejSessions.length === 0) {
      alert('Please load EJ sessions first');
      return;
    }

    setTrainingStatus('training');
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:8001'}/api/train`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          sessions: ejSessions,
          text_weight: config.textWeight,
          statistical_weight: config.statisticalWeight,
          threshold: config.threshold
        }),
      });

      const data = await response.json();
      if (data.success) {
        setTrainingResults(data.training_stats);
        setTrainingStatus('completed');
        onTrainingComplete && onTrainingComplete();
      } else {
        throw new Error(data.detail || 'Training failed');
      }
    } catch (error) {
      console.error('Training failed:', error);
      setTrainingStatus('failed');
      setLoadingStatus(`Training failed: ${error.message}`);
    }
  };

  const updateConfig = (key, value) => {
    const newConfig = { ...config, [key]: parseFloat(value) };

    // Auto-adjust weights to sum to 1
    if (key === 'textWeight') {
      newConfig.statisticalWeight = 1.0 - newConfig.textWeight;
    } else if (key === 'statisticalWeight') {
      newConfig.textWeight = 1.0 - newConfig.statisticalWeight;
    }

    setConfig(newConfig);
  };

  const loadSampleData = () => {
    const sampleSessions = [
      `SESSION START
CARD INSERTED
PIN ENTERED
PIN VERIFIED
BALANCE INQUIRY SELECTED
ACCOUNT BALANCE: $1,250.45
RECEIPT PRINTED
CARD EJECTED
SESSION END`,
      `SESSION START
CARD INSERTED
PIN ENTERED
PIN VERIFIED
WITHDRAW SELECTED
AMOUNT ENTERED: $100
CASH DISPENSED
RECEIPT PRINTED
CARD EJECTED
SESSION END`,
      `SESSION START
CARD INSERTED
PIN ENTERED
PIN VERIFIED
DEPOSIT SELECTED
ENVELOPE INSERTED
DEPOSIT AMOUNT: $500
DEPOSIT COMPLETED
RECEIPT PRINTED
CARD EJECTED
SESSION END`,
      `SESSION START
CARD INSERTED
PIN ENTERED
PIN VERIFIED
TRANSFER SELECTED
ACCOUNT FROM: CHECKING
ACCOUNT TO: SAVINGS
AMOUNT: $200
TRANSFER COMPLETED
RECEIPT PRINTED
CARD EJECTED
SESSION END`,
      `SESSION START
CARD INSERTED
PIN ENTERED
PIN INCORRECT
PIN ENTERED
PIN VERIFIED
CUSTOMER CANCELLED
CARD EJECTED
SESSION END`
    ];

    setEjSessions(sampleSessions);
    setLoadingStatus(`Loaded ${sampleSessions.length} sample normal EJ sessions`);
  };

  return (
    <div className="training-container">
      <div className="training-header">
        <h2>🚀 Train Ensemble Model</h2>
        <p>Load normal EJ sessions to train the ensemble anomaly detection model</p>
      </div>

      <div className="section">
        <h3>📁 Load EJ Session Data</h3>

        <div className="load-options">
          <div className="load-option">
            <h4>🎯 Load from Processed Data (Recommended)</h4>
            <p>Load real EJ sessions from the same data source used by DeepLog dashboard</p>
            <button 
              className="btn btn-primary" 
              onClick={loadFromProcessedData}
              disabled={loadingStatus && loadingStatus.includes('Loading')}
            >
              🎯 Load Real EJ Sessions
            </button>
          </div>

          <div className="load-option">
            <h4>📂 Upload CSV File</h4>
            <p>Upload a CSV file with 'text' column containing EJ sessions</p>
            <input
              type="file"
              accept=".csv"
              onChange={handleFileUpload}
              className="file-input"
            />
          </div>

          <div className="load-option">
            <h4>📝 Paste Raw EJ Log</h4>
            <p>Paste raw EJ log text - it will be automatically sessionized</p>
            <textarea
              rows={8}
              placeholder="Paste raw EJ log text here..."
              className="text-input"
              onBlur={(e) => handleTextInput(e.target.value)}
            />
          </div>

          <div className="load-option">
            <h4>🧪 Use Sample Data</h4>
            <p>Load sample normal EJ sessions for testing</p>
            <button className="sample-btn" onClick={loadSampleData}>
              Load Sample Data
            </button>
          </div>
        </div>

        {loadingStatus && (
          <div className="status-message">
            {loadingStatus}
          </div>
        )}
      </div>

      {ejSessions.length > 0 && (
        <div className="section">
          <h3>📊 Loaded Sessions ({ejSessions.length})</h3>
          <div className="sessions-preview">
            {ejSessions.slice(0, 3).map((session, index) => (
              <div key={index} className="session-preview">
                <h4>Session {index + 1}</h4>
                <pre>{session.substring(0, 200)}...</pre>
              </div>
            ))}
            {ejSessions.length > 3 && (
              <div className="more-sessions">
                ... and {ejSessions.length - 3} more sessions
              </div>
            )}
          </div>
        </div>
      )}

      <div className="section">
        <h3>⚙️ Ensemble Configuration</h3>
        <div className="config-grid">
          <div className="config-item">
            <label>📝 Text Analysis Weight:</label>
            <input
              type="range"
              min="0"
              max="1"
              step="0.1"
              value={config.textWeight}
              onChange={(e) => updateConfig('textWeight', e.target.value)}
            />
            <span>{config.textWeight.toFixed(1)}</span>
          </div>

          <div className="config-item">
            <label>📊 Statistical Analysis Weight:</label>
            <input
              type="range"
              min="0"
              max="1"
              step="0.1"
              value={config.statisticalWeight}
              onChange={(e) => updateConfig('statisticalWeight', e.target.value)}
            />
            <span>{config.statisticalWeight.toFixed(1)}</span>
          </div>

          <div className="config-item">
            <label>🎯 Anomaly Threshold:</label>
            <input
              type="range"
              min="0"
              max="1"
              step="0.05"
              value={config.threshold}
              onChange={(e) => updateConfig('threshold', e.target.value)}
            />
            <span>{config.threshold.toFixed(2)}</span>
          </div>
        </div>
      </div>

      <div className="section">
        <h3>🚀 Train Model</h3>
        <div className="training-controls">
          <button
            className={`train-btn ${trainingStatus}`}
            onClick={trainModel}
            disabled={ejSessions.length === 0 || trainingStatus === 'training'}
          >
            {trainingStatus === 'training' ? '🔄 Training...' : 
             trainingStatus === 'completed' ? '✅ Training Complete' :
             trainingStatus === 'failed' ? '❌ Training Failed' :
             '🚀 Train Ensemble Model'}
          </button>

          {ejSessions.length === 0 && (
            <p className="train-hint">Load EJ sessions first</p>
          )}
        </div>
      </div>

      {trainingResults && (
        <div className="section">
          <h3>📈 Training Results</h3>
          <div className="results-grid">
            <div className="result-card">
              <h4>📁 Training Data</h4>
              <div className="result-value">{trainingResults.num_training_sessions}</div>
              <div className="result-label">Normal Sessions</div>
            </div>

            <div className="result-card">
              <h4>📝 Text Features</h4>
              <div className="result-value">{trainingResults.text_feature_dims}</div>
              <div className="result-label">TF-IDF Dimensions</div>
            </div>

            <div className="result-card">
              <h4>📊 Statistical Features</h4>
              <div className="result-value">{trainingResults.numerical_feature_dims}</div>
              <div className="result-label">Numeric Features</div>
            </div>

            <div className="result-card">
              <h4>🎯 Baseline Score</h4>
              <div className="result-value">{(trainingResults.avg_ensemble_score * 100).toFixed(1)}%</div>
              <div className="result-label">Avg Normal Score</div>
            </div>
          </div>

          <div className="training-success">
            <h4>✅ Training Successful!</h4>
            <p>The ensemble model has been trained on {trainingResults.num_training_sessions} normal EJ sessions.</p>
            <p>You can now use the Prediction tab to analyze new EJ sessions for anomalies.</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default Training;
